-- Aprenda se Divertindo · 83 · Trilha Enem · lote extra 16 (500 questões, de fácil a desafio)
-- Rode depois do 82-trilha-policial-14.sql. Cole tudo no SQL Editor e clique em Run. Rodar de novo apenas atualiza.
-- Questões de cálculo (Matemática, Física e Química) geradas e conferidas por programa: a resposta certa e as erradas
-- saem da própria conta. As demais tratam só de conteúdo consolidado de livro didático. Conferidas contra o banco para não repetir.

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id":7947,"materia":"mat","nivel":0,"enunciado":"Uma camiseta custa R$ 80,00 e está com 25% de desconto. Quanto se economiza?","opcoes":["R$ 20,00","R$ 60,00","R$ 25,00","R$ 40,00"],"explicacao":"25% de 80 = 20."},{"id":7948,"materia":"mat","nivel":0,"enunciado":"Uma camiseta custa R$ 250,00 e está com 12% de desconto. Quanto se economiza?","opcoes":["R$ 30,00","R$ 220,00","R$ 12,00","R$ 60,00"],"explicacao":"12% de 250 = 30."},{"id":7949,"materia":"mat","nivel":0,"enunciado":"Uma camiseta custa R$ 450,00 e está com 8% de desconto. Quanto se economiza?","opcoes":["R$ 36,00","R$ 414,00","R$ 8,00","R$ 72,00"],"explicacao":"8% de 450 = 36."},{"id":7950,"materia":"mat","nivel":2,"enunciado":"Um produto teve aumento de 10% e, no mês seguinte, de mais 20%. O aumento total foi de:","opcoes":["32%","30%","37%","28%"],"explicacao":"Multiplicam-se os fatores: 1,1 × 1,2 = 1,32."},{"id":7951,"materia":"mat","nivel":2,"enunciado":"Um produto teve aumento de 5% e, no mês seguinte, de mais 10%. O aumento total foi de:","opcoes":["15,5%","15%","20,5%","11,5%"],"explicacao":"Multiplicam-se os fatores: 1,05 × 1,1 = 1,16."},{"id":7952,"materia":"mat","nivel":2,"enunciado":"Um produto teve aumento de 30% e, no mês seguinte, de mais 10%. O aumento total foi de:","opcoes":["43%","40%","48%","39%"],"explicacao":"Multiplicam-se os fatores: 1,3 × 1,1 = 1,43."},{"id":7953,"materia":"mat","nivel":3,"enunciado":"Um preço sobe 10% e depois cai 10%. Em relação ao preço inicial, o preço final:","opcoes":["Diminuiu 1%","Ficou igual","Aumentou 1%","Diminuiu 10%"],"explicacao":"(1 + 0,1) × (1 − 0,1) = 0,99."},{"id":7954,"materia":"mat","nivel":3,"enunciado":"Um preço sobe 20% e depois cai 20%. Em relação ao preço inicial, o preço final:","opcoes":["Diminuiu 4%","Ficou igual","Aumentou 4%","Diminuiu 20%"],"explicacao":"(1 + 0,2) × (1 − 0,2) = 0,96."},{"id":7955,"materia":"mat","nivel":3,"enunciado":"Um preço sobe 50% e depois cai 50%. Em relação ao preço inicial, o preço final:","opcoes":["Diminuiu 25%","Ficou igual","Aumentou 25%","Diminuiu 50%"],"explicacao":"(1 + 0,5) × (1 − 0,5) = 0,75."},{"id":7956,"materia":"mat","nivel":1,"enunciado":"Um capital de R$ 2.000,00 é aplicado a juros simples de 2% ao mês por 6 meses. Os juros obtidos são:","opcoes":["R$ 240,00","R$ 2.240,00","R$ 40,00","R$ 120,00"],"explicacao":"J = C·i·t = 2000 × 0,02 × 6."},{"id":7957,"materia":"mat","nivel":1,"enunciado":"Um capital de R$ 5.000,00 é aplicado a juros simples de 3% ao mês por 4 meses. Os juros obtidos são:","opcoes":["R$ 600,00","R$ 5.600,00","R$ 150,00","R$ 300,00"],"explicacao":"J = C·i·t = 5000 × 0,03 × 4."},{"id":7958,"materia":"mat","nivel":1,"enunciado":"Um capital de R$ 1.500,00 é aplicado a juros simples de 4% ao mês por 10 meses. Os juros obtidos são:","opcoes":["R$ 600,00","R$ 2.100,00","R$ 60,00","R$ 300,00"],"explicacao":"J = C·i·t = 1500 × 0,04 × 10."},{"id":7959,"materia":"mat","nivel":3,"enunciado":"Um capital de R$ 2.000,00 é aplicado a juros compostos de 5% ao mês por 2 meses. O montante é:","opcoes":["R$ 2.205,00","R$ 2.200,00","R$ 205,00","R$ 2.315,25"],"explicacao":"M = C·(1 + i)ᵗ = 2000 × 1,05^2."},{"id":7960,"materia":"mat","nivel":3,"enunciado":"Um capital de R$ 8.000,00 é aplicado a juros compostos de 10% ao mês por 3 meses. O montante é:","opcoes":["R$ 10.648,00","R$ 10.400,00","R$ 2.648,00","R$ 11.712,80"],"explicacao":"M = C·(1 + i)ᵗ = 8000 × 1,1^3."},{"id":7961,"materia":"mat","nivel":3,"enunciado":"Um capital de R$ 10.000,00 é aplicado a juros compostos de 20% ao mês por 2 meses. O montante é:","opcoes":["R$ 14.400,00","R$ 14.000,00","R$ 4.400,00","R$ 17.280,00"],"explicacao":"M = C·(1 + i)ᵗ = 10000 × 1,2^2."},{"id":7962,"materia":"mat","nivel":0,"enunciado":"Se 5 cadernos custam R$ 40,00, quanto custam 8 cadernos?","opcoes":["R$ 64,00","R$ 25,00","R$ 43,00","R$ 72,00"],"explicacao":"Cada caderno custa R$ 8,00."},{"id":7963,"materia":"mat","nivel":1,"enunciado":"6 pedreiros constroem um muro em 12 dias. Em quantos dias 4 pedreiros, no mesmo ritmo, constroem o mesmo muro?","opcoes":["18 dias","8 dias","12 dias","19 dias"],"explicacao":"Grandezas inversamente proporcionais: 6 × 12 = 4 × t."},{"id":7964,"materia":"mat","nivel":1,"enunciado":"8 pedreiros constroem um muro em 15 dias. Em quantos dias 12 pedreiros, no mesmo ritmo, constroem o mesmo muro?","opcoes":["10 dias","22,5 dias","15 dias","11 dias"],"explicacao":"Grandezas inversamente proporcionais: 8 × 15 = 12 × t."},{"id":7965,"materia":"mat","nivel":4,"enunciado":"4 máquinas, trabalhando 6 horas por dia, fazem um serviço em 12 dias. Em quantos dias 6 máquinas, trabalhando 8 horas por dia, fazem o mesmo serviço?","opcoes":["6 dias","24 dias","18 dias","12 dias"],"explicacao":"Todas inversamente proporcionais aos dias: 4·6·12 = 6·8·t."},{"id":7966,"materia":"mat","nivel":4,"enunciado":"5 máquinas, trabalhando 8 horas por dia, fazem um serviço em 16 dias. Em quantos dias 10 máquinas, trabalhando 4 horas por dia, fazem o mesmo serviço?","opcoes":["16 dias","32 dias","24 dias","8 dias"],"explicacao":"Todas inversamente proporcionais aos dias: 5·8·16 = 10·4·t."},{"id":7967,"materia":"mat","nivel":2,"enunciado":"Num mapa de escala 1:50.000, a distância entre duas cidades é de 4 cm. A distância real é de:","opcoes":["2 km","20 km","0,2 km","200.000 km"],"explicacao":"4 cm × 50.000 = 200.000 cm = 2 km."},{"id":7968,"materia":"mat","nivel":2,"enunciado":"Num mapa de escala 1:200.000, a distância entre duas cidades é de 3 cm. A distância real é de:","opcoes":["6 km","60 km","0,6 km","600.000 km"],"explicacao":"3 cm × 200.000 = 600.000 cm = 6 km."},{"id":7969,"materia":"mat","nivel":2,"enunciado":"Num mapa de escala 1:25.000, a distância entre duas cidades é de 12 cm. A distância real é de:","opcoes":["3 km","30 km","0,3 km","300.000 km"],"explicacao":"12 cm × 25.000 = 300.000 cm = 3 km."},{"id":7970,"materia":"mat","nivel":0,"enunciado":"Um ônibus percorre 240 km em 3 horas. Sua velocidade média é de:","opcoes":["80 km/h","720 km/h","90 km/h","70 km/h"],"explicacao":"v = distância ÷ tempo."},{"id":7971,"materia":"mat","nivel":0,"enunciado":"Um ônibus percorre 360 km em 4,5 horas. Sua velocidade média é de:","opcoes":["80 km/h","1.620 km/h","90 km/h","70 km/h"],"explicacao":"v = distância ÷ tempo."},{"id":7972,"materia":"mat","nivel":4,"enunciado":"Um carro percorre 120 km a 60 km/h e depois 120 km a 40 km/h. A velocidade média no percurso total é:","opcoes":["48 km/h","50 km/h","53 km/h","24 km/h"],"explicacao":"Tempo total = 2 h + 3 h; vm = 240 ÷ 5."},{"id":7973,"materia":"mat","nivel":4,"enunciado":"Um carro percorre 100 km a 50 km/h e depois 300 km a 100 km/h. A velocidade média no percurso total é:","opcoes":["80 km/h","75 km/h","85 km/h","33,33 km/h"],"explicacao":"Tempo total = 2 h + 3 h; vm = 400 ÷ 5."},{"id":7974,"materia":"mat","nivel":0,"enunciado":"Um terreno retangular mede 12 m por 7 m. Sua área é:","opcoes":["84 m²","38 m²","19 m²","168 m²"],"explicacao":"Área = base × altura."},{"id":7975,"materia":"mat","nivel":1,"enunciado":"Um triângulo tem base 10 cm e altura 6 cm. Sua área é:","opcoes":["30 cm²","60 cm²","16 cm²","15 cm²"],"explicacao":"A = b·h ÷ 2."},{"id":7976,"materia":"mat","nivel":2,"enunciado":"Uma caixa-d'água tem forma de paralelepípedo com 2 m × 1,5 m × 1 m. Quantos litros ela comporta?","opcoes":["3.000 litros","300 litros","3 litros","30.000 litros"],"explicacao":"V = 3 m³ e 1 m³ = 1.000 L."},{"id":7977,"materia":"mat","nivel":2,"enunciado":"Uma caixa-d'água tem forma de paralelepípedo com 5 m × 3 m × 2 m. Quantos litros ela comporta?","opcoes":["30.000 litros","3.000 litros","30 litros","300.000 litros"],"explicacao":"V = 30 m³ e 1 m³ = 1.000 L."},{"id":7978,"materia":"mat","nivel":2,"enunciado":"Uma caixa-d'água tem forma de paralelepípedo com 10 m × 4 m × 1,5 m. Quantos litros ela comporta?","opcoes":["60.000 litros","6.000 litros","60 litros","600.000 litros"],"explicacao":"V = 60 m³ e 1 m³ = 1.000 L."},{"id":7979,"materia":"mat","nivel":3,"enunciado":"Um reservatório cilíndrico tem raio 3 m e altura 10 m. Usando π = 3, seu volume é:","opcoes":["270 m³","180 m³","90 m³","405 m³"],"explicacao":"V = π·r²·h."},{"id":7980,"materia":"mat","nivel":1,"enunciado":"Usando π = 3,14, a área de um círculo de raio 5 cm é:","opcoes":["78,5 cm²","31,4 cm²","15,7 cm²","157 cm²"],"explicacao":"A = π·r²."},{"id":7981,"materia":"mat","nivel":1,"enunciado":"Usando π = 3,14, a área de um círculo de raio 10 cm é:","opcoes":["314 cm²","62,8 cm²","31,4 cm²","628 cm²"],"explicacao":"A = π·r²."},{"id":7982,"materia":"mat","nivel":3,"enunciado":"Se a aresta de um cubo for multiplicada por 2, seu volume fica multiplicado por:","opcoes":["8","2","4","6"],"explicacao":"O volume varia com o cubo da razão de semelhança."},{"id":7983,"materia":"mat","nivel":3,"enunciado":"Se a aresta de um cubo for multiplicada por 3, seu volume fica multiplicado por:","opcoes":["27","3","9","40"],"explicacao":"O volume varia com o cubo da razão de semelhança."},{"id":7984,"materia":"mat","nivel":1,"enunciado":"Uma escada está apoiada num muro. O pé da escada fica a 6 m do muro e o topo toca o muro a 8 m de altura. O comprimento da escada é:","opcoes":["10 m","14 m","11 m","15 m"],"explicacao":"Pitágoras: 6² + 8² = 10²."},{"id":7985,"materia":"mat","nivel":1,"enunciado":"Uma escada está apoiada num muro. O pé da escada fica a 9 m do muro e o topo toca o muro a 12 m de altura. O comprimento da escada é:","opcoes":["15 m","21 m","16 m","22 m"],"explicacao":"Pitágoras: 9² + 12² = 15²."},{"id":7986,"materia":"mat","nivel":1,"enunciado":"Uma escada está apoiada num muro. O pé da escada fica a 5 m do muro e o topo toca o muro a 12 m de altura. O comprimento da escada é:","opcoes":["13 m","17 m","14 m","18 m"],"explicacao":"Pitágoras: 5² + 12² = 13²."},{"id":7987,"materia":"mat","nivel":1,"enunciado":"A média aritmética dos valores 4, 7, 7, 9, 13 é:","opcoes":["8","9","40","8,5"],"explicacao":"Soma dividida pela quantidade."},{"id":7988,"materia":"mat","nivel":2,"enunciado":"A mediana dos valores 4, 7, 7, 9, 13 é:","opcoes":["7","8","4","13"],"explicacao":"Ordena-se os dados e toma-se o valor central (ou a média dos dois centrais)."},{"id":7989,"materia":"mat","nivel":1,"enunciado":"A média aritmética dos valores 10, 2, 8, 6, 4 é:","opcoes":["6","7","30","6,5"],"explicacao":"Soma dividida pela quantidade."},{"id":7990,"materia":"mat","nivel":2,"enunciado":"A mediana dos valores 10, 2, 8, 6, 4 é:","opcoes":["6","7","2","10"],"explicacao":"Ordena-se os dados e toma-se o valor central (ou a média dos dois centrais)."},{"id":7991,"materia":"mat","nivel":1,"enunciado":"A média aritmética dos valores 3, 5, 5, 6, 8, 9 é:","opcoes":["6","6,5","36","9"],"explicacao":"Soma dividida pela quantidade."},{"id":7992,"materia":"mat","nivel":2,"enunciado":"A mediana dos valores 3, 5, 5, 6, 8, 9 é:","opcoes":["5,5","6","3","9"],"explicacao":"Ordena-se os dados e toma-se o valor central (ou a média dos dois centrais)."},{"id":7993,"materia":"mat","nivel":3,"enunciado":"Um aluno tirou notas 6, 8 e 10, com pesos 1, 2 e 2. Sua média ponderada é:","opcoes":["8,4","8","8,9","7,9"],"explicacao":"Soma de nota × peso dividida pela soma dos pesos."},{"id":7994,"materia":"mat","nivel":3,"enunciado":"Um aluno tirou notas 4, 7 e 10, com pesos 2, 3 e 5. Sua média ponderada é:","opcoes":["7,9","7","8,4","7,4"],"explicacao":"Soma de nota × peso dividida pela soma dos pesos."},{"id":7995,"materia":"mat","nivel":0,"enunciado":"Ao lançar um dado comum, qual a probabilidade de sair um número maior que 4?","opcoes":["1/3","1/2","2/3","1/6"],"explicacao":"Casos favoráveis: 5 e 6 (2 em 6)."},{"id":7996,"materia":"mat","nivel":2,"enunciado":"Ao lançar duas moedas, qual a probabilidade de saírem duas coroas?","opcoes":["1/4","1/2","1/3","3/4"],"explicacao":"1/2 × 1/2."},{"id":7997,"materia":"mat","nivel":1,"enunciado":"Numa caixa há 5 bolas brancas e 3 pretas. Retirando uma ao acaso, a probabilidade de ser preta é:","opcoes":["3/8","5/8","3/5","1/3"],"explicacao":"Casos favoráveis ÷ casos possíveis."},{"id":7998,"materia":"mat","nivel":4,"enunciado":"Numa urna há 4 bolas azuis e 6 verdes. Retirando duas, sem reposição, a probabilidade de ambas serem azuis é:","opcoes":["2/15","4/25","4/10","4/15"],"explicacao":"4/10 × 3/9."},{"id":7999,"materia":"mat","nivel":4,"enunciado":"Numa urna há 3 bolas azuis e 7 verdes. Retirando duas, sem reposição, a probabilidade de ambas serem azuis é:","opcoes":["1/15","9/100","3/10","2/15"],"explicacao":"3/10 × 2/9."},{"id":8000,"materia":"mat","nivel":2,"enunciado":"De quantas formas 5 pessoas podem se sentar em 5 cadeiras enfileiradas?","opcoes":["120","25","24","20"],"explicacao":"5! = 120."},{"id":8001,"materia":"mat","nivel":2,"enunciado":"De quantas formas 6 pessoas podem se sentar em 6 cadeiras enfileiradas?","opcoes":["720","36","120","30"],"explicacao":"6! = 720."},{"id":8002,"materia":"mat","nivel":3,"enunciado":"Quantas comissões de 2 pessoas podem ser formadas a partir de 8 pessoas?","opcoes":["28","56","16","42"],"explicacao":"Combinação C(8,2)."},{"id":8003,"materia":"mat","nivel":3,"enunciado":"Quantas comissões de 3 pessoas podem ser formadas a partir de 7 pessoas?","opcoes":["35","210","21","70"],"explicacao":"Combinação C(7,3)."},{"id":8004,"materia":"mat","nivel":3,"enunciado":"Numa corrida com 6 atletas, de quantas formas pode ser formado o pódio (1º, 2º e 3º)?","opcoes":["120","20","216","18"],"explicacao":"A ordem importa: 6 × 5 × 4."},{"id":8005,"materia":"mat","nivel":3,"enunciado":"Numa corrida com 8 atletas, de quantas formas pode ser formado o pódio (1º, 2º e 3º)?","opcoes":["336","56","512","24"],"explicacao":"A ordem importa: 8 × 7 × 6."},{"id":8006,"materia":"mat","nivel":1,"enunciado":"Uma pessoa tem 4 camisas e 3 calças. De quantas formas diferentes pode se vestir com uma camisa e uma calça?","opcoes":["12","7","24","16"],"explicacao":"Princípio multiplicativo: 4 × 3."},{"id":8007,"materia":"mat","nivel":4,"enunciado":"Quantos anagramas tem a palavra BANANA?","opcoes":["60","720","120","36"],"explicacao":"6! ÷ (3! × 2!) = 60, pois A se repete 3 vezes e N, 2."},{"id":8008,"materia":"mat","nivel":2,"enunciado":"Numa progressão aritmética de primeiro termo 3 e razão 4, o 10º termo é:","opcoes":["39","43","47","35"],"explicacao":"aₙ = a₁ + (n − 1)·r."},{"id":8009,"materia":"mat","nivel":2,"enunciado":"Numa progressão aritmética de primeiro termo 7 e razão 5, o 20º termo é:","opcoes":["102","107","112","97"],"explicacao":"aₙ = a₁ + (n − 1)·r."},{"id":8010,"materia":"mat","nivel":3,"enunciado":"A soma dos números naturais de 1 a 50 é:","opcoes":["1.275","2.500","1.325","637"],"explicacao":"S = (1 + 50)·50 ÷ 2."},{"id":8011,"materia":"mat","nivel":3,"enunciado":"Numa progressão geométrica de primeiro termo 5 e razão 2, o 6º termo é:","opcoes":["160","320","15","81"],"explicacao":"aₙ = a₁·qⁿ⁻¹."},{"id":8012,"materia":"mat","nivel":4,"enunciado":"Uma bactéria se divide em duas a cada hora. Partindo de uma bactéria, quantas haverá após 10 horas?","opcoes":["1.024","20","512","100"],"explicacao":"2¹⁰ = 1.024."},{"id":8013,"materia":"mat","nivel":1,"enunciado":"Para f(x) = 2x + 3, o valor de f(5) é:","opcoes":["13","7","10","16"],"explicacao":"Substitui-se x."},{"id":8014,"materia":"mat","nivel":1,"enunciado":"Para f(x) = -3x + 10, o valor de f(2) é:","opcoes":["4","-16","9","-36"],"explicacao":"Substitui-se x."},{"id":8015,"materia":"mat","nivel":3,"enunciado":"As raízes da equação x² − 5x + 6 = 0 são:","opcoes":["2 e 3","-2 e -3","3 e 4","6 e 5"],"explicacao":"Δ = 1; x = (5 ± 1) ÷ 2."},{"id":8016,"materia":"mat","nivel":3,"enunciado":"As raízes da equação x² − 7x + 12 = 0 são:","opcoes":["3 e 4","-3 e -4","4 e 5","12 e 7"],"explicacao":"Δ = 1; x = (7 ± 1) ÷ 2."},{"id":8017,"materia":"mat","nivel":3,"enunciado":"As raízes da equação 2x² − 8x + 6 = 0 são:","opcoes":["1 e 3","-1 e -3","2 e 4","6 e 8"],"explicacao":"Δ = 16; x = (8 ± 4) ÷ 4."},{"id":8018,"materia":"mat","nivel":4,"enunciado":"Uma bola segue a trajetória h(t) = −t² + 6t (h em metros). A 